Section LE64FI.
  Variables (ra sp gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29
             x30 x31 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : fmem) (S : Z) (bs : list Z) (POST : machine_state -> Prop).
  Variables (w1 w2 tb : Z) (d : bitD) (jp : list byte).
  Hypothesis SRC : bytes_at psegs m S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis FRS2 : rw_cells psegs m (bv_unsigned sp + 16) [C8 (Z_to_bv 64 w2); C8 (Z_to_bv 64 tb)].
  Hypothesis FRS1 : rw_cells psegs m (bv_unsigned sp + 32) [C8 (Z_to_bv 64 w1); C8 (Z_to_bv 64 tb)].
  Hypothesis FRB : rw_cells psegs m (bv_unsigned sp + 48) (bitdz_cells S d jp).

  Ltac ldb0 p k :=
    let RX := fresh "RX" in
    pose proof (src_rd psegs m S bs (p + k) SRC ltac:(lia)) as RX;
    rewrite ?Z.add_assoc, ?Z.add_0_r in RX;
    zstep; cbv beta; clear RX.

  (* [comment removed for export] *)
  Lemma fi_ld3f : forall (p b : Z) (y6 y12 y15 y16 y17 y5 : word),
    0 <= p -> p + 8 <= zlen bs -> 0 <= b < 2^30 ->
    (forall (z15 z16 z5 z6 : word),
       evt psegs POST (MS (mkR ra sp gp tp z5 z6 x7 x8 x9 x10 (Z_to_bv 64 (S + p)) (Z_to_bv 64 S) (Z_to_bv 64 (Z.land b 7))
                               x14 z15 z16 (Z_to_bv 64 (le64v bs p)) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                          F (Z_to_bv 64 0x1c278) fc None m (seg_rom psegs))) ->
    evt psegs POST (MS (mkR ra sp gp tp y5 y6 x7 x8 x9 x10 (Z_to_bv 64 (S + p)) y12 (Z_to_bv 64 b) x14 y15 y16 y17 x18 x19 x20
                            x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                       F (Z_to_bv 64 0x1c218) fc None m (seg_rom psegs)).
